INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f54-73be-8bdc-f360c89a508e', 'home', 'hero', 'repeater', '{\"en\":\"Learn German. Build Your Path to Germany.\",\"de\":null}', '{\"de\":null}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":null}', '{\"primary_cta\":\"Explore Courses\",\"secondary_cta\":\"Enroll Now\"}', 1, 1, '2026-10-02 10:16:14', '2026-10-04 06:21:30', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f5a-72e4-80be-8938ee0ed2a8', 'home', 'stats', 'cards', '{\"en\":\"Home Statistics\",\"ne\":\"????? ????????\",\"de\":\"Statistiken\"}', '{\"de\":null}', '{\"de\":null}', '[]', 1, 2, '2026-10-02 10:16:14', '2026-10-04 06:36:42', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f78-7358-8b92-8ee4c726ccea', 'home', 'journey', 'repeater', '{\"en\":\"Start Your German Learning Journey With Us\"}', NULL, '{\"en\":\"<p>Learning a new language opens doors to new cultures, education and professional opportunities. At Himalayan Education Pathways, we provide structured German language education designed to help learners progress confidently from beginner to upper-intermediate levels.</p>\"}', NULL, 1, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f8b-7042-a551-891c70355318', 'home', 'about', 'single_block', '{\"en\":\"Learn German in Kathmandu With Himalayan Education Pathways\"}', NULL, '{\"en\":\"<p>Himalayan Education Pathways is a German language institute located in Chabahil, Kathmandu, providing structured language education from beginner A1 through B2. Our courses are designed to develop practical communication alongside grammar, vocabulary, pronunciation, listening, reading and writing. Whether you are preparing for a German language examination, Ausbildung, higher education, professional opportunities or everyday life in Germany, we provide a structured path for improving your German.</p>\"}', '{\"cta\":\"Explore All Courses\"}', 1, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fa7-726a-b711-79112d16e1e9', 'home', 'popular-categories', 'cards', '{\"en\":\"Explore Our German Learning Programs\"}', NULL, '{\"en\":\"<p>Choose the learning path that matches your current German level and future goals.</p>\"}', NULL, 1, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fc5-7143-b349-1a2c76151477', 'home', 'why-choose-us', 'cards', '{\"en\":\"Why Choose Himalayan Education Pathways for German Classes?\"}', NULL, '{\"en\":\"<p>Learning German requires consistency, practical communication and a clear progression from one language level to another. Our programs are structured to help learners gradually build confidence while developing all four essential language skills.</p>\"}', '{\"cta\":\"View All Courses\"}', 1, 6, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fdf-73cf-b0e1-8f6b9562c9d7', 'home', 'leadership', 'repeater', '{\"en\":\"Meet Our Leadership\"}', NULL, '{\"en\":\"<p>Meet the people guiding Himalayan Education Pathways and its commitment to quality German language education.</p>\"}', NULL, 1, 7, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
