INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4ff6-73c9-bfe7-c87df62b33f4', 'home', 'career-cta', 'single_block', '{\"en\":\"Planning Your Future in Germany?\"}', NULL, '{\"en\":\"<p>Build the German language foundation required for your future plans.</p><p>Whether your goal is Ausbildung, higher education, professional development or everyday communication, start your German journey with structured language learning.</p>\"}', '{\"cta\":\"Explore German Courses\"}', 1, 9, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT IGNORE INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4ff9-7228-b147-3ee4afd7deee', 'about', 'about-intro', 'single_block', '{\"en\":\"Start Your German Journey With Us\"}', NULL, '{\"en\":\"<p>Himalayan Education Pathways is a German language education institute located in Chabahil–7, Kathmandu, Nepal. Our goal is to provide structured, practical and accessible German language education to learners preparing for academic, professional and personal opportunities. From complete beginners starting A1 to learners progressing through A2, B1 and B2, our courses focus on building confidence across speaking, listening, reading and writing.</p>\"}', NULL, 1, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
