INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5054-715d-8ebe-1ee644ab9fb4', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Where can I learn German in Kathmandu?\"}', '{\"en\":\"<p>Himalayan Education Pathways provides German language classes from A1 to B2 at our institute in Chabahil–7, Kathmandu.</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5057-716f-893b-11422a726dec', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"What German courses do you offer?\"}', '{\"en\":\"<p>We currently provide German A1, A2, B1 and B2 language courses.</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-505a-7113-9068-3fdf817b45fe', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Can complete beginners join German A1?\"}', '{\"en\":\"<p>Yes. German A1 is specifically designed for learners starting German with little or no previous knowledge.</p>\"}', NULL, NULL, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-505e-7033-9bf3-3cb11619c6ac', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is the German A1 course?\"}', '{\"en\":\"<p>The A1 course runs for approximately two months with around two hours of classes per day.</p>\"}', NULL, NULL, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5062-718b-addb-65675e2c9344', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German A2?\"}', '{\"en\":\"<p>German A2 runs for approximately two months with around two hours of classes per day.</p>\"}', NULL, NULL, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5066-7336-ac31-7096415c6b2a', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German B1?\"}', '{\"en\":\"<p>German B1 runs for approximately 2.5 months with around two hours of classes per day.</p>\"}', NULL, NULL, 6, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5069-7035-becd-a7061845f4ee', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German B2?\"}', '{\"en\":\"<p>German B2 runs for approximately 2.5 months with around two hours of classes per day.</p>\"}', NULL, NULL, 7, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-506d-73c7-bb9b-4de95a989a9f', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Do you provide German exam preparation?\"}', '{\"en\":\"<p>Yes. Exam-oriented preparation can include speaking, listening, reading, writing and mock-test exercises for A1–B2 learners.</p>\"}', NULL, NULL, 8, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
