INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a10106-153e-7013-8d31-1db4681d355c', '01a0fc1d-4f54-73be-8bdc-f360c89a508e', '{\"en\":\"Learn German. Build Your Path to Germany.\",\"de\":null}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":null}', NULL, NULL, 0, '2026-10-03 09:08:58', '2026-10-04 06:21:30');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a10593-256c-719b-b823-bbcf74e20809', '01a0fc1d-4f54-73be-8bdc-f360c89a508e', '{\"en\":\"2\",\"de\":null}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":null}', '2', NULL, 0, '2026-10-04 06:21:31', '2026-10-04 06:21:31');
INSERT IGNORE INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a105a1-0ba1-70bd-8f71-1768f3cd6a08', '01a0fc1d-4f5a-72e4-80be-8938ee0ed2a8', '{\"en\":\"2\",\"de\":null}', '{\"en\":\"<p>German Language Levels</p>\",\"de\":null}', NULL, NULL, 0, '2026-10-04 06:36:42', '2026-10-04 06:36:42');
INSERT IGNORE INTO `posts` (`id`, `type`, `title`, `slug`, `summary`, `content`, `is_featured`, `status`, `published_at`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50a9-7316-a577-fcd5e312d50a', 'post', '{\"en\":\"How to Learn German A1 in Nepal: A Beginner\'s Guide\",\"ne\":\"test\",\"de\":null}', 'how-to-learn-german-a1-in-nepal-a-beginners-guide', '{\"en\":\"Starting German for the first time? Learn what A1 covers and how to build a strong foundation in grammar, vocabulary, speaking and listening.\",\"ne\":\"test\",\"de\":null}', '{\"en\":\"<p>German A1 is the starting point for learners beginning their German language journey. Whether you\'re learning German for Ausbildung, education, professional opportunities, travel or future plans in Germany, developing a strong A1 foundation can make progression to higher levels much easier.</p><h3>What Is German A1?</h3><p>A1 is the beginner level within the Common European Framework of Reference for Languages (CEFR). At this stage, learners begin developing the ability to understand and use simple German expressions related to familiar everyday situations.</p><h3>What Do You Learn in German A1?</h3><p>Typical topics include:</p><p><br></p><p>Students also begin learning essential German grammar and sentence structures.</p><h3>Develop All Four Language Skills</h3><p><strong>Speaking:</strong> Practice introducing yourself, asking questions and responding in simple conversations.</p><p><strong>Listening:</strong> Become familiar with common German expressions and basic spoken conversations.</p><p><strong>Reading:</strong> Learn to understand simple German notices, messages and short texts.</p><p><strong>Writing:</strong> Practice writing basic sentences, messages and personal information.</p><h3>Learn Vocabulary in Context</h3><p>Instead of memorizing isolated words, learn vocabulary around topics such as family, food, travel and daily activities. This makes vocabulary easier to recall when speaking and writing.</p><h3>Practice German Every Day</h3><p>Consistency is important when learning a new language. Even short daily activities can help:</p><p><br></p><h3>Take Structured German Classes</h3><p>Structured classes provide learners with a clear progression and regular opportunities to practice German. Students looking for German A1 classes in Kathmandu can begin their learning journey at Himalayan Education Pathways in Chabahil.</p>\",\"de\":null}', 0, 'published', '2026-09-05 10:16:00', 1, '{\"en\":\"How to Learn German A1 in Nepal | Beginner\'s Guide\",\"de\":null}', '{\"en\":\"Learn how to start German A1 in Nepal, including vocabulary, grammar, speaking, listening, reading and effective beginner study strategies.\",\"de\":null}', '{\"de\":null}', '2026-10-02 10:16:14', '2026-10-02 12:35:28', NULL);
