INSERT IGNORE INTO `posts` (`id`, `type`, `title`, `slug`, `summary`, `content`, `is_featured`, `status`, `published_at`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a1028a-82c2-71e6-bf16-5f627ca48f93', 'news', '{\"en\":\"How to Learn German A1 in Nepal: A Beginner\'s Guide\",\"de\":\"Wie man in Nepal Deutsch auf A1-Niveau lernt: Ein Leitfaden für Anfänger\"}', 'how-to-learn-german-a1-in-nepal-a-beginners-guide-1', '{\"en\":\"How to Learn German A1 in Nepal: A Beginner\'s Guide\",\"de\":\"Wie man in Nepal Deutsch auf A1-Niveau lernt: Ein Leitfaden für Anfänger\"}', '{\"en\":\"<p>How to Learn German A1 in Nepal: A Beginner\'s Guide</p>\",\"de\":null}', 0, 'published', NULL, 0, '{\"de\":null}', '{\"de\":null}', '{\"de\":null}', '2026-10-03 16:13:14', '2026-10-04 06:13:45', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5084-73e3-97da-23fed31118fb', '{\"en\":\"German A1\",\"de\":null}', 'german-a1', '{\"en\":\"Build a strong foundation in German with essential vocabulary, basic grammar, pronunciation and everyday communication.\",\"de\":null}', '{\"en\":\"<h4>Overview</h4><p>German A1 develops the fundamental skills required to begin communicating in German. Students gradually learn how to introduce themselves, ask basic questions, understand simple conversations and communicate about common everyday topics.</p><h4>What You\'ll Learn</h4><p><br></p><h4>Skills Developed</h4><p><strong>Speaking:</strong> Introduce yourself and participate in simple everyday conversations.</p><p><strong>Listening:</strong> Understand basic expressions and slowly spoken German.</p><p><strong>Reading:</strong> Understand simple notices, messages and short texts.</p><p><strong>Writing:</strong> Write basic sentences, messages and personal information.</p>\",\"de\":null}', NULL, '500.00', '2 Months', 1, 1, 1, '{\"en\":\"German A1 Classes in Kathmandu | A1 German Course Nepal\",\"de\":null}', '{\"en\":\"Join German A1 classes in Kathmandu at Himalayan Education Pathways. Learn beginner German grammar, vocabulary, speaking, listening, reading and writing.\",\"de\":null}', '{\"de\":null}', '2026-10-02 10:16:14', '2026-10-04 06:33:12', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-508f-72b0-bcfa-2791fec69808', '{\"en\":\"German A2\"}', 'german-a2-classes-kathmandu', '{\"en\":\"Continue your German journey by expanding your vocabulary, grammar and communication skills for everyday situations.\"}', '{\"en\":\"<p>German A2 builds upon the foundation developed during A1. Students learn to communicate more confidently about familiar situations such as family, education, shopping, travel, work and daily activities.</p><h4>Key Learning Areas</h4><ul><li>Expanded vocabulary</li><li>A2 grammar</li><li>Everyday conversations</li><li>Describing experiences</li><li>Talking about past events</li><li>Travel situations</li><li>Work and education</li><li>Reading comprehension</li><li>Listening exercises</li><li>Structured writing</li><li>Speaking practice</li></ul>\"}', NULL, NULL, '2 Months', 1, 1, 2, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5093-7368-aefe-a7c87e400f3f', '{\"en\":\"German B1\"}', 'german-b1-classes-kathmandu', '{\"en\":\"Develop independent German communication skills through intermediate speaking, listening, reading, writing and grammar.\"}', '{\"en\":\"<p>German B1 helps learners become increasingly independent German users. Students develop the ability to communicate about familiar topics, describe experiences, explain plans and express opinions.</p><h4>Key Learning Areas</h4><ul><li>Intermediate German grammar</li><li>Expanded vocabulary</li><li>German conversations</li><li>Expressing opinions</li><li>Describing experiences</li><li>Reading longer texts</li><li>Listening comprehension</li><li>Structured writing</li><li>Speaking exercises</li><li>Exam-oriented activities</li></ul><p>B1 can be particularly relevant for learners developing German skills for Ausbildung, study, work or life in Germany.</p>\"}', NULL, NULL, '2.5 Months', 1, 1, 3, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5097-724b-a562-8e82563e144f', '{\"en\":\"German B2\"}', 'german-b2-classes-kathmandu', '{\"en\":\"Improve fluency, accuracy and confidence while developing advanced vocabulary, grammar and communication abilities.\"}', '{\"en\":\"<p>German B2 focuses on developing stronger fluency, accuracy and independent communication. Learners work with more complex vocabulary, grammar, texts and conversations.</p><h4>Key Learning Areas</h4><ul><li>Advanced grammar</li><li>Expanded vocabulary</li><li>Complex conversations</li><li>Expressing detailed opinions</li><li>Professional communication</li><li>Reading complex texts</li><li>Listening comprehension</li><li>Structured writing</li><li>Speaking fluency</li><li>Exam-oriented preparation</li></ul>\"}', NULL, NULL, '2.5 Months', 1, 1, 4, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-509c-72e9-a603-444ef782857f', '{\"en\":\"German Exam Preparation\"}', 'german-exam-preparation-kathmandu', '{\"en\":\"Prepare across speaking, listening, reading and writing with exam-oriented exercises and mock-test activities.\"}', '{\"en\":\"<p>Preparing for a German language examination requires both language knowledge and familiarity with exam-style activities. Our exam preparation focuses on developing confidence across the four major language skills.</p><p><strong>Speaking:</strong> Practice structured conversations, pronunciation and responding to common speaking tasks.</p><p><strong>Listening:</strong> Develop strategies for understanding spoken German and identifying important information.</p><p><strong>Reading:</strong> Improve comprehension of German texts, notices, messages and longer passages.</p><p><strong>Writing:</strong> Practice structured German writing appropriate to your language level.</p><p><strong>Mock Test Practice:</strong> Work with exam-oriented exercises to identify areas that need improvement.</p><h4>Available Levels</h4><ul><li>A1 Exam Preparation</li><li>A2 Exam Preparation</li><li>B1 Exam Preparation</li><li>B2 Exam Preparation</li></ul><p><em>Himalayan Education Pathways provides German language and exam preparation. Unless formally authorized, the institute should not be presented as an official Goethe examination center.</em></p>\"}', NULL, NULL, NULL, 0, 1, 5, '{\"en\":\"German Exam Preparation Kathmandu | A1 A2 B1 B2\"}', NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT IGNORE INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50a1-714e-8bd3-bcd5a122804c', '{\"en\":\"German for Ausbildung\"}', 'german-language-for-ausbildung-nepal', '{\"en\":\"Build German communication skills progressively from A1 toward the language level appropriate for your individual Ausbildung pathway.\"}', '{\"en\":\"<p>Planning to pursue vocational training in Germany? Developing German communication skills is an important part of preparing for Ausbildung and everyday life in Germany. Himalayan Education Pathways provides structured German courses from A1 through B2 for learners preparing for their future in Germany.</p><h4>Build Your German Step by Step</h4><p><strong>A1:</strong> Build your German foundation.</p><p><strong>A2:</strong> Become more confident in everyday communication.</p><p><strong>B1:</strong> Develop independent German communication.</p><p><strong>B2:</strong> Strengthen fluency for more complex situations.</p><h4>What You\'ll Develop</h4><ul><li>Everyday German communication</li><li>Speaking confidence</li><li>Listening comprehension</li><li>Grammar</li><li>Vocabulary</li><li>Reading</li><li>Writing</li><li>Practical German communication</li></ul><p><em>Language requirements differ between Ausbildung programs, employers and circumstances. Students should verify the requirements applicable to their individual pathway.</em></p>\"}', NULL, NULL, NULL, 0, 1, 6, '{\"en\":\"German Language for Ausbildung Nepal | German Classes Kathmandu\"}', NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
